/**
 * Restore the CC0-licensed Kenney "Voxel Pack" textures used by the
 * Minecraft-style voxel demo from an immutable GitHub revision.
 *
 * Kenney's direct download URLs are generated by the website and can redirect
 * to HTML when they expire. Pinning every file to a commit and verifying its
 * Git blob digest keeps clean builds reproducible without committing binaries.
 */
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

